import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth } from './helpers';

test.describe(`incident commander: change the severity, reassign, or escalate an incident`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`after the commander changes the severity of an incident, every team member sees the updated severity on the dashboard within 5s`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    try {
      await loginViaHash(pageA, 0);
      await loginViaHash(pageB, 1);

      // Node 0: create an incident with 'high' severity
      await pageA.getByTestId('action-create_incident').click();
      await pageA.getByTestId('field-title').fill('Severity update incident');
      await pageA.getByTestId('field-description').fill('Testing severity update propagation');
      await pageA.getByTestId('field-severity').fill('high');
      await pageA.getByTestId('action-create_incident').click();

      // Node 0: navigate to the incident and escalate severity to 'critical'
      await pageA.getByTestId('item-incident').filter({ hasText: 'Severity update incident' }).click();
      await pageA.getByTestId('field-severity').fill('critical');
      await pageA.getByTestId('action-update_incident').click();

      // Node 1: should see 'critical' on the dashboard within 5s
      const incidentOnB = pageB.getByTestId('item-incident').filter({ hasText: 'Severity update incident' });
      await expect(incidentOnB).toBeVisible({ timeout: 5_000 });
      await expect(incidentOnB).toContainText('critical');
    } finally {
      await ctxA.close();
      await ctxB.close();
    }
  });

  test(`after the commander reassigns the incident, the new assignee is reflected for everyone`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    try {
      await loginViaHash(pageA, 0);
      await loginViaHash(pageB, 1);

      // Node 0: create an incident and reassign it to 'bob'
      await pageA.getByTestId('action-create_incident').click();
      await pageA.getByTestId('field-title').fill('Reassign incident');
      await pageA.getByTestId('field-description').fill('Testing reassignment propagation');
      await pageA.getByTestId('field-severity').fill('medium');
      await pageA.getByTestId('action-create_incident').click();

      await pageA.getByTestId('item-incident').filter({ hasText: 'Reassign incident' }).click();
      await pageA.getByTestId('field-assignee').fill('bob');
      await pageA.getByTestId('action-update_incident').click();

      // Node 1: navigates to the incident and sees 'bob' as assignee
      await pageB.getByTestId('item-incident').filter({ hasText: 'Reassign incident' }).click();
      await expect(pageB.getByText('bob')).toBeVisible({ timeout: 5_000 });
    } finally {
      await ctxA.close();
      await ctxB.close();
    }
  });
});
